import java.io.BufferedReader; import java.io.InputStreamReader; import java.io.PrintWriter; import java.util.StringTokenizer; public class Main { public static void main(String[] args) throws java.lang.Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(System.out); String line = br.readLine(); if (line == null || line.trim().isEmpty()) return; StringTokenizer st = new StringTokenizer(line); int n = Integer.parseInt(st.nextToken()); long k = Long.parseLong(st.nextToken()); long[] a = new long[n]; st = new StringTokenizer(br.readLine()); for (int i = 0; i < n; i++) { a[i] = Long.parseLong(st.nextToken()); } if (k > 0) { int iterations = (k % 2 == 0) ? 2 : 1; for (int step = 0; step < iterations; step++) { long max = Long.MIN_VALUE; for (int i = 0; i < n; i++) { if (a[i] > max) max = a[i]; } for (int i = 0; i < n; i++) { a[i] = max - a[i]; } } } StringBuilder sb = new StringBuilder(); for (int i = 0; i < n; i++) { sb.append(a[i]).append(i == n - 1 ? "" : " "); } out.println(sb.toString()); out.flush(); out.close(); } }